    // On success, this command will end the pre-boot stage and this controller
    // will be replaced by a runtime controller.
    fn start_microvm(&mut self) -> Result<VmmData, VmmActionError> {
        if let Some(enclave_config) = &self.vm_resources.enclave {
            let enclave_config = enclave_config.clone();
            crate::nitro_enclave::enclave_builder::build_and_boot_enclave(
                &self.instance_info,
                self.vm_resources,
                &enclave_config,
                self.event_manager,
                self.seccomp_filters,
            )
            .map(|vmm| {
                self.built_vmm = Some(vmm);
                VmmData::Empty
            })
            .map_err(|e| VmmActionError::StartMicrovm(StartMicrovmError::from(e)))
        } else {
            build_and_boot_microvm(
            | SetEntropyDevice(_)
            | SetMemoryHotplugDevice(_)
            | StartMicroVm
            | UpdateMachineConfiguration(_) => Err(VmmActionError::OperationNotSupportedPostBoot),
        }
    }

    /// Creates a new `RuntimeApiController`.
    pub fn new(vmm: Arc<Mutex<Vmm>>) -> Self {
        Self { vmm }
    }

    /// Tears down the devices whose removal the guest has acknowledged.
    pub fn complete_hotplug_removals(&mut self, event_manager: &mut EventManager) {
        self.vmm
            .lock()
            .expect("Poisoned lock")
            .complete_hotplug_removals(event_manager);
    }

    /// Pauses the microVM by pausing the vCPUs.
    ///
    /// Device emulation is not stopped here; `ApiServerAdapter::handle_request` stops
    /// polling the event loop once this returns `Ok`.
    pub fn pause(&mut self) -> Result<VmmData, VmmActionError> {
        let pause_start_us = get_time_us(ClockType::Monotonic);

        self.vmm.lock().expect("Poisoned lock").pause_vm()?;

        let elapsed_time_us =
            update_metric_with_elapsed_time(&METRICS.latencies_us.vmm_pause_vm, pause_start_us);
        info!("'pause vm' VMM action took {} us.", elapsed_time_us);

        Ok(VmmData::Empty)
    }

