    fn set_entropy_device(&mut self, cfg: EntropyDeviceConfig) -> Result<VmmData, VmmActionError> {
        self.boot_path = true;
        self.vm_resources.build_entropy_device(cfg)?;
        Ok(VmmData::Empty)
    }

    fn set_memory_hotplug_device(
        &mut self,
        cfg: MemoryHotplugConfig,
    ) -> Result<VmmData, VmmActionError> {
        self.boot_path = true;
        self.vm_resources.set_memory_hotplug_config(cfg)?;
        Ok(VmmData::Empty)
    }

    fn set_enclave_config(&mut self, cfg: EnclaveConfig) -> Result<VmmData, VmmActionError> {
        self.boot_path = true;
        self.vm_resources.set_enclave_config(cfg);
        Ok(VmmData::Empty)
    }

    // On success, this command will end the pre-boot stage and this controller
    // will be replaced by a runtime controller.
    fn start_microvm(&mut self) -> Result<VmmData, VmmActionError> {
        if let Some(enclave_config) = &self.vm_resources.enclave {
            let enclave_config = enclave_config.clone();
            crate::nitro_enclave::enclave_builder::build_and_boot_enclave(
                &self.instance_info,
                self.vm_resources,
                &enclave_config,
                self.event_manager,
                self.seccomp_filters,
            )
            .map(|vmm| {
                self.built_vmm = Some(vmm);
                VmmData::Empty
            })
            .map_err(|e| VmmActionError::StartMicrovm(StartMicrovmError::from(e)))
        } else {
            build_and_boot_microvm(
            | SetEntropyDevice(_)
            | SetMemoryHotplugDevice(_)
            | StartMicroVm
            | UpdateMachineConfiguration(_) => Err(VmmActionError::OperationNotSupportedPostBoot),
        }
    }

