    MsixTableOutOfRange(u8, u64, u64, u64),
    /// BAR{0} sparse mmap area at offset {1:#x} size {2:#x} does not fit in region of size {3:#x}
    SparseMmapAreaOutOfRange(u8, u64, u64, u64),
